def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "u-": 3, "^": 4}

    def apply():
        op = operators.pop()
        if op == "u-":
            values.append(-values.pop())
            return

        b = values.pop()
        a = values.pop()

        if op == "+":
            values.append(a + b)
        elif op == "-":
            values.append(a - b)
        elif op == "*":
            values.append(a * b)
        elif op == "^":
            if b < 0:
                raise ValueError
            values.append(pow(a, b))
        else:
            if b == 0:
                raise ZeroDivisionError
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            values.append(quotient if op == "/" else a - b * quotient)

    i = 0
    expecting_operand = True

    try:
        while i < len(expr):
            c = expr[i]

            if c.isspace():
                i += 1
            elif "0" <= c <= "9":
                value = 0
                while i < len(expr) and "0" <= expr[i] <= "9":
                    value = value * 10 + (ord(expr[i]) - ord("0"))
                    i += 1
                values.append(value)
                expecting_operand = False
            elif c == "(":
                operators.append(c)
                i += 1
                expecting_operand = True
            elif c == ")":
                while operators[-1] != "(":
                    apply()
                operators.pop()
                i += 1
                expecting_operand = False
            elif c == "-" and expecting_operand:
                operators.append("u-")
                i += 1
            else:
                while operators and operators[-1] != "(":
                    top = precedence[operators[-1]]
                    current = precedence[c]
                    if top < current or (top == current and c == "^"):
                        break
                    apply()
                operators.append(c)
                i += 1
                expecting_operand = True

        while operators:
            apply()
        return values[0]
    except (ZeroDivisionError, ValueError):
        return "error"
